mapper.select:
SELECT * FROM TB_QNA
WHERE USERNAME = #{username}
ORDER BY REG_DATE DESC

SELECT ID, USER_ID, USERNAME, PRODUCT_ID, QUESTION, ANSWER, IFNULL(IS_SECRET,0) AS isSecret, REG_DATE, UPD_DATE
FROM TB_QNA
WHERE PRODUCT_ID = #{productId}
ORDER BY REG_DATE DESC

    LIMIT #{limit}


    OFFSET #{offset}

mapper.insert:
INSERT INTO TB_QNA ( PRODUCT_ID
                   , USERNAME
                   , QUESTION
                   , IS_SECRET
                   , REG_DATE)
VALUES ( #{productId}
       , #{username}
       , #{question}
       , #{isSecret}
       , NOW())

mapper.delete:
DELETE FROM TB_QNA
WHERE ID = #{id}
  AND USERNAME = #{username}
